                                                      onIntegers:
                                                          restageA2uiWriteIntegers,
                                                      onDoubles:
                                                          restageA2uiWriteDoubles,
                                                      onNumbers:
                                                          restageA2uiWriteNumbers,
                                                      onBooleans:
                                                          restageA2uiWriteBooleans,
