/// Builds the generated custom-only A2UI catalog identified by
/// [restageA2uiCatalogId].
///
/// To compose a different catalog, use
/// [buildRestageCatalogItems] with [buildRestageCatalogDefinitions] and assign an
/// application-owned catalog ID.
CatalogImplementation buildRestageCatalog() => CatalogImplementation(
      components: buildRestageCatalogItems(),
      definitions: buildRestageCatalogDefinitions(),
      protocolVersion: A2uiProtocolVersion.v1_0,
      title: 'Restage A2UI Catalog',
      description:
          'A2UI component catalog generated from Restage widget source.',
      schemaId: restageA2uiCatalogId,
      id: restageA2uiCatalogId,
      instructions: _restageA2uiSystemPromptFragments.join('\n'),
    );

Widget? _restageA2uiBuildChild(ChildWidgetBuilder buildChild, Object? child) {
  return child is ComponentNode<ComponentImplementation>
      ? buildChild(child)
      : null;
}

Widget _restageA2uiRequireChild(
    ChildWidgetBuilder buildChild, Object? child, String propertyContext) {
  if (child is! ComponentNode<ComponentImplementation> || child.isPlaceholder) {
    throw StateError(
        'Required A2UI child "$propertyContext" could not resolve. Provide a non-empty String id for a component registered on this surface.');
  }
  return buildChild(child);
}

List<Widget> _restageA2uiBuildChildren(
        ChildWidgetBuilder buildChild, Object? children) =>
    [
      if (children is List)
        for (final child in children)
          if (child is ComponentNode<ComponentImplementation>)
            buildChild(child),
    ];

Color? _restageA2uiColor(String? value) {
  if (value == null || value.isEmpty) return null;
  final normalized = value.startsWith('#')
      ? value.substring(1)
      : value.startsWith(
          '0x',
        )
          ? value.substring(2)
          : value;
  final parsed = int.tryParse(normalized, radix: 16);
  if (parsed == null) return null;
  if (normalized.length <= 6) return Color(0xFF000000 | parsed);
  return Color(parsed);
}

FontWeight _restageA2uiFontWeight(
  num? value,
  FontWeight fallback,
) {
  if (value == null) return fallback;
  final index = value.toInt();
  if (index < 0 || index >= FontWeight.values.length) {
    return fallback;
  }
  return FontWeight.values[index];
}

enum _RestageA2uiSourceKind { literal, path, call, localOverride }

typedef _RestageA2uiControlledBuilder = Widget Function(
  BuildContext context,
  Object? rawValue,
  bool sourcePresent,
  _RestageA2uiSourceKind sourceKind,
  ValueChanged<Object?> write,
);

final class _RestageA2uiControlledValue extends StatefulWidget {
  const _RestageA2uiControlledValue({
    required this.dataContext,
    required this.resolvedProps,
    required this.propertyName,
    required this.source,
    required this.sourcePresent,
    required this.surfaceId,
    required this.catalogId,
    required this.componentId,
    required this.field,
    required this.selfPath,
    required this.builder,
  });

  final DataContext dataContext;
  final ReadonlySignal<NodeProps> resolvedProps;
  final String propertyName;
  final Object? source;
  final bool sourcePresent;
  final String surfaceId;
  final String? catalogId;
  final String componentId;
  final String field;
  final String selfPath;
  final _RestageA2uiControlledBuilder builder;

  @override
  State<_RestageA2uiControlledValue> createState() =>
      _RestageA2uiControlledValueState();
}

final class _RestageA2uiControlledValueState
    extends State<_RestageA2uiControlledValue> {
  void Function()? _unsubscribe;
  var _epoch = 0;
  late _RestageA2uiSourceDescriptor _descriptor;
  late _RestageA2uiSemanticIdentity _semanticIdentity;
  Object? _sourceValue;
  var _sourcePresent = false;
  var _hasOverride = false;
  Object? _overrideValue;

  @override
  void initState() {
    super.initState();
    _adoptBinding(
      _RestageA2uiSourceDescriptor.from(widget.source),
      _RestageA2uiSemanticIdentity.from(widget),
    );
    _subscribe();
  }

  @override
  void didUpdateWidget(_RestageA2uiControlledValue oldWidget) {
    super.didUpdateWidget(oldWidget);
    final nextDescriptor = _RestageA2uiSourceDescriptor.from(widget.source);
    final nextSemantic = _RestageA2uiSemanticIdentity.from(widget);
    final bindingChanged = !_descriptor.sameBinding(nextDescriptor) ||
        _semanticIdentity != nextSemantic ||
        oldWidget.componentId != widget.componentId ||
        oldWidget.field != widget.field ||
        oldWidget.selfPath != widget.selfPath ||
        !identical(oldWidget.resolvedProps, widget.resolvedProps);
    if (bindingChanged) {
      _invalidateSubscription();
      _adoptBinding(nextDescriptor, nextSemantic);
      _subscribe();
      return;
    }

    final literalPayloadChanged =
        nextDescriptor.kind == _RestageA2uiSourceKind.literal &&
            (!_restageA2uiLiteralEqual(oldWidget.source, widget.source) ||
                oldWidget.sourcePresent != widget.sourcePresent);
    if (literalPayloadChanged && !_hasOverride) {
      _invalidateSubscription();
      _sourceValue = widget.source;
      _sourcePresent = widget.sourcePresent;
      _subscribe();
    }
  }

  void _adoptBinding(
    _RestageA2uiSourceDescriptor descriptor,
    _RestageA2uiSemanticIdentity semanticIdentity,
  ) {
    _descriptor = descriptor;
    _semanticIdentity = semanticIdentity;
    _sourceValue =
        ComponentProps.unwrap(widget.resolvedProps.peek()[widget.propertyName]);
    _sourcePresent = widget.sourcePresent;
    _hasOverride = false;
    _overrideValue = null;
  }

  void _subscribe() {
    final subscribedEpoch = _epoch;
    void onValue(Object? value) {
      if (!mounted || subscribedEpoch != _epoch || _hasOverride) return;
      setState(() {
        _sourceValue = value;
        _sourcePresent = widget.sourcePresent;
      });
    }

    final props = widget.resolvedProps;
    var initial = true;
    _unsubscribe = props.subscribe((value) {
      if (!initial) {
        onValue(ComponentProps.unwrap(value[widget.propertyName]));
      }
    });
    initial = false;
    _sourceValue = ComponentProps.unwrap(props.peek()[widget.propertyName]);
  }

  void _invalidateSubscription() {
    final unsubscribe = _unsubscribe;
    _unsubscribe = null;
    _epoch += 1;
    unsubscribe?.call();
  }

  void _write(Object? next) {
    if (!mounted) return;
    if (_descriptor.kind == _RestageA2uiSourceKind.path) {
      widget.dataContext.set(_descriptor.path!, next);
      return;
    }

    _invalidateSubscription();
    _hasOverride = true;
    _overrideValue = next;
    widget.dataContext.set(widget.selfPath, next);
    if (mounted) setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final overridden = _hasOverride;
    return widget.builder(
      context,
      overridden ? _overrideValue : _sourceValue,
      overridden ? true : _sourcePresent,
      overridden ? _RestageA2uiSourceKind.localOverride : _descriptor.kind,
      _write,
    );
  }

  @override
  void dispose() {
    _invalidateSubscription();
    super.dispose();
  }
}

final class _RestageA2uiSourceDescriptor {
  const _RestageA2uiSourceDescriptor._(
    this.kind, {
    this.path,
    this.callName,
    this.callArgs,
    this.callCatalogId,
  });

  factory _RestageA2uiSourceDescriptor.from(Object? source) {
    if (source is Map && source.containsKey('@path')) {
      final path = source['@path'];
      if (path is! String) {
        throw ArgumentError.value(
          path,
          'source.path',
          'A controlled A2UI path must be a String.',
        );
      }
      return _RestageA2uiSourceDescriptor._(
        _RestageA2uiSourceKind.path,
        path: path,
      );
    }
    if (source is Map && source.containsKey('@call')) {
      final callName = source['@call'];
      if (callName != null && callName is! String) {
        throw ArgumentError.value(
          callName,
          'source.call',
          'A controlled A2UI call name must be a String or null.',
        );
      }
      final args = source['args'];
      return _RestageA2uiSourceDescriptor._(
        _RestageA2uiSourceKind.call,
        callName: callName as String?,
        callCatalogId: source['catalogId'] as String?,
        callArgs: args is Map ? args : const <String, Object?>{},
      );
    }
    return const _RestageA2uiSourceDescriptor._(
      _RestageA2uiSourceKind.literal,
    );
  }

  final _RestageA2uiSourceKind kind;
  final String? path;
  final String? callName;
  final String? callCatalogId;
  final Map<Object?, Object?>? callArgs;

  bool sameBinding(_RestageA2uiSourceDescriptor other) {
    if (kind != other.kind) return false;
    return switch (kind) {
      _RestageA2uiSourceKind.literal => true,
      _RestageA2uiSourceKind.path => path == other.path,
      _RestageA2uiSourceKind.call => callName == other.callName &&
          callCatalogId == other.callCatalogId &&
          _restageA2uiCallIdentityEqual(callArgs, other.callArgs),
      _RestageA2uiSourceKind.localOverride => false,
    };
  }
}

final class _RestageA2uiSemanticIdentity {
  const _RestageA2uiSemanticIdentity(
    this.surfaceId,
    this.catalogId,
    this.dataModel,
    this.contextPath,
  );

  factory _RestageA2uiSemanticIdentity.from(
    _RestageA2uiControlledValue widget,
  ) =>
      _RestageA2uiSemanticIdentity(
        widget.surfaceId,
        widget.catalogId,
        widget.dataContext.dataModel,
        widget.dataContext.path,
      );

  final String surfaceId;
  final String? catalogId;
  final Object dataModel;
  final String contextPath;

  @override
  bool operator ==(Object other) =>
      other is _RestageA2uiSemanticIdentity &&
      surfaceId == other.surfaceId &&
      catalogId == other.catalogId &&
      identical(dataModel, other.dataModel) &&
      contextPath == other.contextPath;

  @override
  int get hashCode => Object.hash(
        surfaceId,
        catalogId,
        identityHashCode(dataModel),
        contextPath,
      );
}

bool _restageA2uiCallIdentityEqual(Object? left, Object? right) {
  if (identical(left, right)) return true;
  if (left is num && right is num) return left == right;
  if (left is List && right is List) {
    if (left.length != right.length) return false;
    for (var index = 0; index < left.length; index += 1) {
      if (!_restageA2uiCallIdentityEqual(left[index], right[index])) {
        return false;
      }
    }
    return true;
  }
  if (left is Map && right is Map) {
    if (left.length != right.length) return false;
    for (final entry in left.entries) {
      if (!right.containsKey(entry.key) ||
          !_restageA2uiCallIdentityEqual(entry.value, right[entry.key])) {
        return false;
      }
    }
    return true;
  }
  return left == right;
}

bool _restageA2uiLiteralEqual(Object? left, Object? right) {
  if (identical(left, right)) return true;
  if (left == null || right == null) return false;
  if (left is num && right is num) {
    return left.runtimeType == right.runtimeType && left == right;
  }
  if (left is List && right is List) {
    if (left.length != right.length) return false;
    for (var index = 0; index < left.length; index += 1) {
      if (!_restageA2uiLiteralEqual(left[index], right[index])) return false;
    }
    return true;
  }
  if (left is Map && right is Map) {
    if (left.length != right.length) return false;
    for (final entry in left.entries) {
      if (!right.containsKey(entry.key) ||
          !_restageA2uiLiteralEqual(entry.value, right[entry.key])) {
        return false;
      }
    }
    return true;
  }
  return left.runtimeType == right.runtimeType && left == right;
}

num? _restageA2uiNumber(
  Object? rawValue,
  _RestageA2uiSourceKind sourceKind,
) {
  if (rawValue is num) return rawValue;
  if ((sourceKind == _RestageA2uiSourceKind.path ||
          sourceKind == _RestageA2uiSourceKind.call) &&
      rawValue is String) {
    return num.tryParse(rawValue);
  }
  return null;
}

bool? _restageA2uiBool(
  Object? rawValue,
  _RestageA2uiSourceKind sourceKind,
) {
  if (rawValue is bool) return rawValue;
  if (sourceKind == _RestageA2uiSourceKind.path) {
    if (rawValue is String) {
      final normalized = rawValue.toLowerCase();
      if (normalized == 'true') return true;
      if (normalized == 'false') return false;
    }
    if (rawValue is num) return rawValue != 0;
  }
  if (sourceKind == _RestageA2uiSourceKind.call) {
    return rawValue != null;
  }
  return null;
}

String? _restageA2uiString(Object? rawValue) => rawValue?.toString();

String? _restageA2uiEnumName(Object? rawValue) =>
    rawValue is Enum ? rawValue.name : rawValue?.toString();

final class _SignalFunction extends FunctionImplementation {
  _SignalFunction(this.current)
      : super(name: 'currentValue', argumentSchema: S.object());
  final Signal<Object?> current;
  int executions = 0;
  @override
  Object? execute(Map<String, dynamic> args, DataContext context,
      [CancellationSignal? cancellationSignal]) {
    executions++;
    return current;
  }
}

DataContext _context(DataModel model,
        {String path = '/', Signal<Object?>? value}) =>
    DataContext(model, (_, _, _) => value?.value, path,
        protocolVersion: A2uiProtocolVersion.v1_0);

final class _DirectConfiguration {
  const _DirectConfiguration(
      {required this.context,
      this.source = 7,
      this.present = true,
      this.surface = 's',
      this.catalog = restageA2uiCatalogId,
      this.component = 'root',
      this.field = 'value',
      this.selfPath = '/local/value'});
  final DataContext context;
  final Object? source;
  final bool present;
  final String surface, catalog, component, field, selfPath;
}

// Stands in for the upstream node's resolved props; tests set the resolved value.
Signal<NodeProps> _resolved(Object? value) =>
    signal<NodeProps>({'props_value': value});

Future<void> _pumpDirect(
    WidgetTester tester,
    ValueNotifier<_DirectConfiguration> configuration,
    Signal<NodeProps> resolved,
    {void Function(ValueChanged<Object?>)? capture}) async {
  await tester.pumpWidget(MaterialApp(
      home: ValueListenableBuilder<_DirectConfiguration>(
    valueListenable: configuration,
    builder: (context, c, _) => _RestageA2uiControlledValue(
      dataContext: c.context,
      resolvedProps: resolved,
      propertyName: 'props_value',
      source: c.source,
      sourcePresent: c.present,
      surfaceId: c.surface,
      catalogId: c.catalog,
      componentId: c.component,
      field: c.field,
      selfPath: c.selfPath,
      builder: (context, raw, present, kind, write) {
        capture?.call(write);
        return Text('${present ? raw ?? 'null' : 'absent'}:${kind.name}');
      },
    ),
  )));
}

// A template parent from another catalog; generated components take id lists only.
final _rowsCatalog = CatalogImplementation(
    id: 'test:rows',
    protocolVersion: A2uiProtocolVersion.v1_0,
    components: [
      ComponentImplementation(
          name: 'Rows',
          schema: S.object(properties: {'children': CommonSchemas.childList}),
          builder: (context, node, props, buildChild) {
            final children = node.props.peek()['children'];
            return Column(children: [
              if (children is List)
                for (final child in children)
                  if (child is ComponentNode<ComponentImplementation>)
                    buildChild(child)
            ]);
          }),
    ]);

MessageProcessor<ComponentImplementation> _processor(
    {List<FunctionImplementation> functions = const [],
    ValidationConfig validationConfig =
        const ValidationConfig(allowOrphanComponents: true)}) {
  final catalog = CatalogImplementation(
      id: restageA2uiCatalogId,
      components: buildRestageCatalogItems(),
      functions: functions,
      protocolVersion: A2uiProtocolVersion.v1_0);
  final processor = MessageProcessor<ComponentImplementation>(
      catalogs: [catalog, _rowsCatalog],
      defaultVersion: A2uiProtocolVersion.v1_0,
      validationConfig: validationConfig);
  addTearDown(processor.dispose);
  return processor;
}

Map<String, Object?> _component(String type, Map<String, Object?> values,
        {String id = 'root'}) =>
    {
      'id': id,
      'component': type,
      for (final entry in values.entries) 'props_${entry.key}': entry.value,
    };

Future<SurfaceModel<ComponentImplementation>> _mount(
    WidgetTester tester,
    MessageProcessor<ComponentImplementation> processor,
    List<Map<String, Object?>> components,
    {Map<String, Object?> data = const {}}) async {
  processor.processMessages({
    'version': 'v1.0',
    'createSurface': {
      'surfaceId': 's',
      'catalogId': restageA2uiCatalogId,
      'dataModel': data,
      'components': components
    }
  });
  final surface = processor.model.getSurface('s')!;
  await tester.pumpWidget(
      MaterialApp(home: Scaffold(body: A2uiSurface(surface: surface))));
  return surface;
}

void _update(MessageProcessor<ComponentImplementation> processor,
        List<Map<String, Object?>> components) =>
    processor.processMessages({
      'version': 'v1.0',
      'updateComponents': {'surfaceId': 's', 'components': components}
    });

Map<String, Object?> _families(Object? Function(String, Object?) source) => {
      for (final entry in <String, Object?>{
        'enabled': true,
        'label': 'remote',
        'choice': 'alpha',
        'strings': <String>['a'],
        'integers': <int>[1],
        'doubles': <double>[1.5],
        'numbers': <num>[1, 1.5],
        'booleans': <bool>[true],
        'maybeNumbers': <num?>[1, null, 1.5],
        'maybeIntegers': <int>[1],
      }.entries)
        entry.key: source(entry.key, entry.value),
    };

void main() {
  testWidgets(
      'literal presence, null, numeric representation and overrides remain distinct',
      (tester) async {
    final model = DataModel();
    addTearDown(model.dispose);
    final context = _context(model);
    final c =
        ValueNotifier(_DirectConfiguration(context: context, source: <num>[1]));
    addTearDown(c.dispose);
    final resolved = _resolved(<num>[1]);
    late ValueChanged<Object?> write;
    await _pumpDirect(tester, c, resolved, capture: (value) => write = value);
    expect(find.text('[1]:literal'), findsOneWidget);
    resolved.value = {
      'props_value': <num>[1.0]
    };
    c.value = _DirectConfiguration(context: context, source: <num>[1.0]);
    await tester.pump();
    expect(find.text('[1.0]:literal'), findsOneWidget);
    resolved.value = {};
    c.value =
        _DirectConfiguration(context: context, source: null, present: false);
    await tester.pump();
    expect(find.text('absent:literal'), findsOneWidget);
    resolved.value = {'props_value': null};
    c.value = _DirectConfiguration(context: context, source: null);
    await tester.pump();
    expect(find.text('null:literal'), findsOneWidget);
    write(null);
    await tester.pump();
    resolved.value = {'props_value': 9};
    c.value = _DirectConfiguration(context: context, source: 9);
    await tester.pump();
    expect(find.text('null:localOverride'), findsOneWidget);
    write(41);
    await tester.pump();
    expect(model.get('/local/value'), 41);
    expect(find.text('41:localOverride'), findsOneWidget);
  });

  testWidgets('each semantic identity axis independently resets an override',
      (tester) async {
    final first = DataModel();
    final second = DataModel();
    addTearDown(first.dispose);
    addTearDown(second.dispose);
    final context = _context(first);
    final c = ValueNotifier(_DirectConfiguration(context: context));
    addTearDown(c.dispose);
    late ValueChanged<Object?> write;
    await _pumpDirect(tester, c, _resolved(7),
        capture: (value) => write = value);
    write(41);
    await tester.pump();
    c.value = _DirectConfiguration(context: _context(first));
    await tester.pump();
    expect(find.text('41:localOverride'), findsOneWidget);
    for (final changed in [
      _DirectConfiguration(context: context, surface: 'other'),
      _DirectConfiguration(
          context: context,
          catalog:
              'restage:catalog/sha256/9ed800c83d013e379de60376dfde4100ea4868701ee5568ba02f51a47e1848e3'),
      _DirectConfiguration(context: _context(second)),
      _DirectConfiguration(context: _context(first, path: '/nested')),
      _DirectConfiguration(context: context, component: 'other'),
      _DirectConfiguration(context: context, field: 'other'),
      _DirectConfiguration(context: context, selfPath: '/other'),
    ]) {
      c.value = _DirectConfiguration(context: context);
      await tester.pump();
      write(41);
      await tester.pump();
      c.value = changed;
      await tester.pump();
      expect(find.text('7:literal'), findsOneWidget);
    }
  });

  testWidgets(
      'path write-through, rebinding, kind transitions and retained writers after disposal',
      (tester) async {
    final model = DataModel();
    addTearDown(model.dispose);
    model.set('/a', 1);
    model.set('/b', 2);
    final context = _context(model);
    final c = ValueNotifier(
        _DirectConfiguration(context: context, source: const {'@path': '/a'}));
    addTearDown(c.dispose);
    final resolved = _resolved(1);
    late ValueChanged<Object?> write;
    await _pumpDirect(tester, c, resolved, capture: (value) => write = value);
    write(41);
    await tester.pump();
    expect(model.get('/a'), 41);
    resolved.value = {'props_value': 2};
    c.value =
        _DirectConfiguration(context: context, source: const {'@path': '/b'});
    await tester.pump();
    expect(find.text('2:path'), findsOneWidget);
    resolved.value = {'props_value': 12};
    await tester.pump();
    expect(find.text('12:path'), findsOneWidget);
    write(13);
    await tester.pump();
    expect(model.get('/b'), 13);
    expect(model.get('/a'), 41);
    await tester.pumpWidget(const SizedBox.shrink());
    write(55);
    expect(model.get('/b'), 13);
    for (final source in [
      7,
      const {'@call': 'value'}
    ]) {
      c.value = _DirectConfiguration(context: context, source: source);
      await _pumpDirect(tester, c, _resolved(7),
          capture: (value) => write = value);
      await tester.pumpWidget(const SizedBox.shrink());
      write(55);
      expect(model.get('/local/value'), isNull);
    }
  });

  testWidgets(
      'call equality, catalog and argument rebinding, override and disposal follow resolved props',
      (tester) async {
    final model = DataModel();
    addTearDown(model.dispose);
    final context = _context(model);
    final c =
        ValueNotifier(_DirectConfiguration(context: context, source: const {
      '@call': 'value',
      'args': {'path': 'business', 'call': 'business'}
    }));
    addTearDown(c.dispose);
    final resolved = _resolved(7);
    late ValueChanged<Object?> write;
    await _pumpDirect(tester, c, resolved, capture: (v) => write = v);
    expect(find.text('7:call'), findsOneWidget);
    resolved.value = {'props_value': 8};
    await tester.pump();
    expect(find.text('8:call'), findsOneWidget);
    write(41);
    await tester.pump();
    resolved.value = {'props_value': 9};
    await tester.pump();
    expect(find.text('41:localOverride'), findsOneWidget);
    c.value = _DirectConfiguration(context: context, source: const {
      '@call': 'value',
      'args': {'call': 'business', 'path': 'business'}
    });
    await tester.pump();
    expect(find.text('41:localOverride'), findsOneWidget);
    c.value = _DirectConfiguration(context: context, source: const {
      '@call': 'value',
      'args': {'path': 'changed'}
    });
    await tester.pump();
    expect(find.text('9:call'), findsOneWidget);
    write(41);
    await tester.pump();
    c.value = _DirectConfiguration(context: context, source: const {
      '@call': 'value',
      'catalogId': 'other',
      'args': {'path': 'changed'}
    });
    await tester.pump();
    expect(find.text('9:call'), findsOneWidget);
    await tester.pumpWidget(const SizedBox.shrink());
    resolved.value = {'props_value': 10};
    await tester.pump();
    expect(tester.takeException(), isNull);
  });

  testWidgets(
      'generated literal, path and call controls render and preserve local overrides',
      (tester) async {
    for (final source in [
      7,
      const {'@path': '/value'},
      const {'@call': 'currentValue'}
    ]) {
      final signalValue = signal<Object?>(7);
      final function = _SignalFunction(signalValue);
      final processor = _processor(functions: [function]);
      final surface = await _mount(tester, processor, [
        _component('ControlledInt', {'value': source})
      ], data: {
        'value': 7
      });
      expect(find.text('controlled-value:7'), findsOneWidget);
      expect(function.executions,
          source is Map && source.containsKey('@call') ? 1 : 0,
          reason: 'The generated helper reuses upstream resolved properties.');
      await tester.tap(find.byKey(const ValueKey('controlled-write-41')));
      await tester.pump();
      expect(find.text('controlled-value:41'), findsOneWidget);
      if (source is Map && source.containsKey('@path')) {
        expect(surface.dataModel.get('/value'), 41);
        surface.dataModel.set('/value', 12);
        await tester.pump();
        expect(find.text('controlled-value:12'), findsOneWidget);
      } else {
        expect(surface.dataModel.get('/restage_root/props_value'), 41);
        signalValue.value = 13;
        _update(processor, [
          _component('ControlledInt', {'value': source is Map ? source : 13})
        ]);
        await tester.pump();
        expect(find.text('controlled-value:41'), findsOneWidget);
      }
      await tester.tap(find.byKey(const ValueKey('controlled-write-null')));
      await tester.pump();
      expect(find.text('controlled-value:null'), findsOneWidget);
      await tester.pumpWidget(const SizedBox.shrink());
    }
  });

  testWidgets(
      'valid component IDs have safe injective literal and call storage',
      (tester) async {
    const storageById = {
      'constructor': 'restage_constructor',
      'prototype': 'restage_prototype',
      '__proto__': 'restage___proto__',
      'restage_constructor': 'restage_restage_constructor',
      'café': 'restage_caf%C3%A9',
    };
    expect(storageById.values.toSet(), hasLength(storageById.length));
    for (final entry in storageById.entries) {
      for (final source in [
        7,
        const {'@call': 'currentValue'}
      ]) {
        final value = signal<Object?>(7);
        final processor = _processor(
            functions: [_SignalFunction(value)],
            validationConfig: ValidationConfig.strict);
        final surface = await _mount(tester, processor, [
          _component('ControlledScalarHost', {'child': entry.key}),
          _component('ControlledInt', {'value': source}, id: entry.key),
        ]);
        expect(find.text('controlled-value:7'), findsOneWidget);
        await tester.tap(find.byKey(const ValueKey('controlled-write-41')));
        await tester.pump();
        expect(tester.takeException(), isNull);
        expect(find.text('controlled-value:41'), findsOneWidget);
        expect(surface.dataModel.get('/${entry.value}/props_value'), 41);
        value.value = 12;
        await tester.pump();
        expect(find.text('controlled-value:41'), findsOneWidget);
        await tester.pumpWidget(const SizedBox.shrink());
      }
    }
  });

