      fixture.onIntegers([41]);
      fixture.onDoubles([4.5]);
      fixture.onNumbers([4, 4.5]);
      fixture.onBooleans([false]);
      fixture.onMaybeNumbers([4, null, 4.5]);
      fixture.onMaybeIntegers(null);
