  testWidgets(
      'two fields do not cross-talk and changing the child ID resets its override',
      (tester) async {
    final processor = _processor();
    await _mount(tester, processor, [
      _component('ControlledIntPair', {'first': 1, 'second': 2})
    ]);
    await tester.tap(find.byKey(const ValueKey('pair-write-first')));
    await tester.pump();
    _update(processor, [
      _component('ControlledIntPair', {'first': 3, 'second': 4})
    ]);
    await tester.pump();
    expect(find.text('pair-first:11'), findsOneWidget);
    expect(find.text('pair-second:4'), findsOneWidget);
    await tester.tap(find.byKey(const ValueKey('pair-write-second')));
    await tester.pump();
    expect(find.text('pair-first:11'), findsOneWidget);
    expect(find.text('pair-second:22'), findsOneWidget);
    await tester.pumpWidget(const SizedBox.shrink());
    final next = _processor();
    await _mount(tester, next, [
      _component('ControlledScalarHost', {'child': 'a'}),
      _component('ControlledInt', {'value': 7}, id: 'a')
    ]);
    await tester.tap(find.byKey(const ValueKey('controlled-write-41')));
    await tester.pump();
    _update(next, [
      _component('ControlledInt', {'value': 8}, id: 'a')
    ]);
    await tester.pump();
    expect(find.text('controlled-value:41'), findsOneWidget);
    _update(next, [
      _component('ControlledScalarHost', {'child': 'b'}),
      _component('ControlledInt', {'value': 9}, id: 'b')
    ]);
    await tester.pump();
    expect(find.text('controlled-value:9'), findsOneWidget);
    expect(tester.takeException(), isNull);
  });
